import { fileURLToPath } from "node:url";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { createDb } from "./index.js";

/** Folder holding the SQL migrations generated by drizzle-kit (apps/server/drizzle). */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../../drizzle", import.meta.url));

/** Postgres is still starting or recovering (57P03), or not listening yet. */
function isStartingUp(error: unknown): boolean {
  for (
    let e = error as { code?: string; cause?: unknown } | undefined;
    e;
    e = e.cause as typeof e
  ) {
    if (e.code === "57P03" || e.code === "ECONNREFUSED") return true;
  }
  return false;
}

/**
 * Applies every pending migration. Safe to run repeatedly. Retries for up to `waitMs` while the
 * database is starting up: after a deploy restarts the stack, `service_healthy` can pass while
 * Postgres is still replaying its WAL, which crashed the app container once (Image run 87).
 */
export async function runMigrations(databaseUrl: string, waitMs = 60_000): Promise<void> {
  const deadline = Date.now() + waitMs;
  for (;;) {
    const { db, close } = createDb(databaseUrl, { max: 1 });
    try {
      await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
      return;
    } catch (error) {
      if (!isStartingUp(error) || Date.now() > deadline) throw error;
      console.warn("Database not ready yet, retrying migrations in 2 s.");
    } finally {
      await close();
    }
    await new Promise((resolve) => setTimeout(resolve, 2000));
  }
}
